1	"use client";
2	
3	import { useState, useMemo, useRef, useEffect, useId } from "react";
4	import styles from "./roi-calculator.module.css";
5	
6	// ─── Types ────────────────────────────────────────────────────────────────────
7	
8	type BillingPeriod = "monthly" | "quarterly" | "annual";
9	type PlanKey = "starter" | "growth" | "pro";
10	type PresetKey = "startup" | "midsize" | "enterprise";
11	
12	interface CalcState {
13	  billing: BillingPeriod;
14	  plan: PlanKey;
15	  teamSize: number;
16	  manualHours: number;
17	  hourlyRate: number;
18	  toolCost: number;
19	}
20	
21	interface CalcResult {
22	  bmo: number;
23	  byr: number;
24	  laborSaved: number;
25	  savings: number;
26	  net: number;
27	  roi: number;
28	  monthlyBenefit: number;
29	  hrsSaved: number;
30	  prodGain: number;
31	}
32	
33	// ─── Constants ────────────────────────────────────────────────────────────────
34	
35	const PLAN_PRICES: Record<PlanKey, Record<BillingPeriod, number>> = {
36	  starter: { monthly: 999, quarterly: 899, annual: 799 },
37	  growth: { monthly: 1999, quarterly: 1799, annual: 1599 },
38	  pro: { monthly: 3499, quarterly: 3149, annual: 2799 },
39	};
40	
41	const PLAN_LABELS: Record<PlanKey, string> = {
42	  starter: "Starter",
43	  growth: "Growth",
44	  pro: "Pro",
45	};
46	
47	const BILLING_LABELS: Record<BillingPeriod, string> = {
48	  monthly: "Monthly",
49	  quarterly: "Quarterly",
50	  annual: "Annual",
51	};
52	
53	const BILLING_BADGES: Partial<Record<BillingPeriod, string>> = {
54	  quarterly: "Save 10%",
55	  annual: "Save 20%",
56	};
57	
58	const PRESETS: Record<PresetKey, Omit<CalcState, "billing">> = {
59	  startup: {
60	    plan: "starter",
61	    teamSize: 8,
62	    manualHours: 6,
63	    hourlyRate: 50,
64	    toolCost: 8000,
65	  },
66	  midsize: {
67	    plan: "growth",
68	    teamSize: 30,
69	    manualHours: 8,
70	    hourlyRate: 60,
71	    toolCost: 25000,
72	  },
73	  enterprise: {
74	    plan: "pro",
75	    teamSize: 100,
76	    manualHours: 10,
77	    hourlyRate: 75,
78	    toolCost: 80000,
79	  },
80	};
81	
82	const PRESET_META: Record<PresetKey, { label: string; emoji: string }> = {
83	  startup: { label: "Startup", emoji: "🚀" },
84	  midsize: { label: "Growth Agency", emoji: "📈" },
85	  enterprise: { label: "Enterprise", emoji: "🏢" },
86	};
87	
88	const FIELD_TOOLTIPS = {
89	  teamSize:
90	    "Total number of people on your team who spend time on manual tasks.",
91	  manualHours:
92	    "Average hours per person per week spent on tasks Boldteq would handle — reporting, QA, revisions, coordination.",
93	  hourlyRate:
94	    "Average fully-loaded cost per hour for those team members (salary + benefits ÷ 2,080).",
95	  toolCost:
96	    "Annual spend on tools, contractors, or freelancers that Boldteq would replace.",
97	};
98	
99	// ─── Helpers ─────────────────────────────────────────────────────────────────
100	
101	function fmt(n: number): string {
102	  return "$" + Math.round(n).toLocaleString("en-US");
103	}
104	
105	function fmtRoi(n: number): string {
106	  return Math.round(n).toLocaleString("en-US") + "%";
107	}
108	
109	function fmtHrs(n: number): string {
110	  return Math.round(n).toLocaleString("en-US") + " hrs";
111	}
112	
113	function fmtPct(n: number): string {
114	  return n.toFixed(1) + "%";
115	}
116	
117	function sliderBg(value: number, min: number, max: number): string {
118	  const pct = ((value - min) / (max - min)) * 100;
119	  return `linear-gradient(to right, #019ae6 0%, #019ae6 ${pct}%, #e2e8f0 ${pct}%, #e2e8f0 100%)`;
120	}
121	
122	// ─── Tooltip ─────────────────────────────────────────────────────────────────
123	
124	function Tooltip({ text }: { text: string }) {
125	  const [visible, setVisible] = useState(false);
126	  const id = useId();
127	
128	  return (
129	    <span className={styles.tooltipWrap}>
130	      <button
131	        type="button"
132	        className={styles.tooltipBtn}
133	        aria-describedby={visible ? id : undefined}
134	        aria-label="More information"
135	        onMouseEnter={() => setVisible(true)}
136	        onMouseLeave={() => setVisible(false)}
137	        onFocus={() => setVisible(true)}
138	        onBlur={() => setVisible(false)}
139	      >
140	        ?
141	      </button>
142	      {visible && (
143	        <span role="tooltip" id={id} className={styles.tooltipBubble}>
144	          {text}
145	        </span>
146	      )}
147	    </span>
148	  );
149	}
150	
151	// ─── Dollar input field ───────────────────────────────────────────────────────
152	
153	interface DollarFieldProps {
154	  label: string;
155	  tooltip: string;
156	  value: number;
157	  min?: number;
158	  onChange: (v: number) => void;
159	}
160	
161	function DollarField({
162	  label,
163	  tooltip,
164	  value,
165	  min = 0,
166	  onChange,
167	}: DollarFieldProps) {
168	  const inputId = useId();
169	
170	  return (
171	    <div className={styles.field}>
172	      <label htmlFor={inputId} className={styles.fieldLabel}>
173	        {label}
174	        <Tooltip text={tooltip} />
175	      </label>
176	      <div className={styles.dollarWrap}>
177	        <span className={styles.dollarSign} aria-hidden="true">
178	          $
179	        </span>
180	        <input
181	          id={inputId}
182	          type="number"
183	          min={min}
184	          value={value}
185	          onChange={(e) => {
186	            const parsed = parseFloat(e.target.value);
187	            if (!isNaN(parsed) && parsed >= min) onChange(parsed);
188	          }}
189	          className={styles.dollarInput}
190	        />
191	      </div>
192	    </div>
193	  );
194	}
195	
196	// ─── Metric card ──────────────────────────────────────────────────────────────
197	
198	interface MetricCardProps {
199	  label: string;
200	  value: string;
201	  sub?: string;
202	}
203	
204	function MetricCard({ label, value, sub }: MetricCardProps) {
205	  return (
206	    <div className={styles.metricCard}>
207	      <div className={styles.metricLabel}>{label}</div>
208	      <div className={styles.metricValue}>{value}</div>
209	      {sub && <div className={styles.metricSub}>{sub}</div>}
210	    </div>
211	  );
212	}
213	
214	// ─── Main component ───────────────────────────────────────────────────────────
215	
216	export function RoiCalculator() {
217	  const [state, setState] = useState<CalcState>({
218	    billing: "monthly",
219	    plan: "growth",
220	    teamSize: 10,
221	    manualHours: 12,
222	    hourlyRate: 55,
223	    toolCost: 800,
224	  });
225	
226	  const teamSizeRef = useRef<HTMLInputElement | null>(null);
227	  const manualHoursRef = useRef<HTMLInputElement | null>(null);
228	
229	  // Keep range slider fill track in sync
230	  useEffect(() => {
231	    const el = teamSizeRef.current;
232	    if (!el) return;
233	    el.style.background = sliderBg(state.teamSize, 1, 200);
234	  }, [state.teamSize]);
235	
236	  useEffect(() => {
237	    const el = manualHoursRef.current;
238	    if (!el) return;
239	    el.style.background = sliderBg(state.manualHours, 1, 40);
240	  }, [state.manualHours]);
241	
242	  function patch(partial: Partial<CalcState>) {
243	    setState((prev) => ({ ...prev, ...partial }));
244	  }
245	
246	  function applyPreset(key: PresetKey) {
247	    setState((prev) => ({ ...prev, ...PRESETS[key] }));
248	  }
249	
250	  const result = useMemo<CalcResult>(() => {
251	    const bmo = PLAN_PRICES[state.plan][state.billing];
252	    const byr = bmo * 12;
253	    const laborSaved =
254	      state.manualHours * state.hourlyRate * state.teamSize * 52;
255	    const savings = laborSaved + state.toolCost;
256	    const net = savings - byr;
257	    const roi = byr > 0 ? (net / byr) * 100 : 0;
258	    const monthlyBenefit = savings / 12 - bmo;
259	    const hrsSaved = state.manualHours * state.teamSize * 52;
260	    const totalHrs = 40 * state.teamSize * 52;
261	    const prodGain = totalHrs > 0 ? (hrsSaved / totalHrs) * 100 : 0;
262	
263	    return {
264	      bmo,
265	      byr,
266	      laborSaved,
267	      savings,
268	      net,
269	      roi,
270	      monthlyBenefit,
271	      hrsSaved,
272	      prodGain,
273	    };
274	  }, [state]);
275	
276	  const netIsPositive = result.net >= 0;
277	
278	  const teamSizeId = useId();
279	  const manualHoursId = useId();
280	
281	  return (
282	    <section className={styles.section}>
283	      <div className={styles.container}>
284	        {/* Header */}
285	        <div className={styles.header}>
286	          <div className={styles.eyebrowBadge}>ROI Calculator</div>
287	          <h2 className={styles.title}>
288	            See Your Real Savings Before You Commit
289	          </h2>
290	          <p className={styles.subtitle}>
291	            Adjust the inputs to match your team. We&apos;ll show exactly how
292	            much Boldteq saves you annually compared to hiring.
293	          </p>
294	        </div>
295	
296	        {/* Preset buttons */}
297	        <div className={styles.presets}>
298	          {(Object.keys(PRESETS) as PresetKey[]).map((key) => {
299	            const { label, emoji } = PRESET_META[key];
300	            const preset = PRESETS[key];
301	            const isActive =
302	              state.plan === preset.plan &&
303	              state.teamSize === preset.teamSize &&
304	              state.manualHours === preset.manualHours;
305	
306	            return (
307	              <button
308	                key={key}
309	                type="button"
310	                className={`${styles.presetBtn} ${isActive ? styles.presetBtnActive : ""}`}
311	                onClick={() => applyPreset(key)}
312	              >
313	                <span aria-hidden="true">{emoji}</span>
314	                <span>{label}</span>
315	              </button>
316	            );
317	          })}
318	        </div>
319	
320	        {/* Two-column layout */}
321	        <div className={styles.layout}>
322	          {/* LEFT: Inputs */}
323	          <div className={styles.leftPanel}>
324	            <div className={styles.panelTitle}>Tell us about your team</div>
325	
326	            {/* Plan Selection block */}
327	            <div className={styles.planBlock}>
328	              {/* Billing toggle */}
329	              <div className={styles.billingToggle}>
330	                {(Object.keys(BILLING_LABELS) as BillingPeriod[]).map((b) => (
331	                  <button
332	                    key={b}
333	                    type="button"
334	                    className={`${styles.billingBtn} ${state.billing === b ? styles.billingBtnActive : ""}`}
335	                    onClick={() => patch({ billing: b })}
336	                  >
337	                    <span>{BILLING_LABELS[b]}</span>
338	                    {BILLING_BADGES[b] && (
339	                      <span className={styles.billingBadge}>
340	                        {BILLING_BADGES[b]}
341	                      </span>
342	                    )}
343	                  </button>
344	                ))}
345	              </div>
346	
347	              {/* Plan buttons */}
348	              <div className={styles.planButtons}>
349	                {(Object.keys(PLAN_LABELS) as PlanKey[]).map((p) => (
350	                  <button
351	                    key={p}
352	                    type="button"
353	                    className={`${styles.planBtn} ${state.plan === p ? styles.planBtnActive : ""}`}
354	                    onClick={() => patch({ plan: p })}
355	                  >
356	                    <span className={styles.planBtnName}>
357	                      {PLAN_LABELS[p]}
358	                    </span>
359	                    <span className={styles.planBtnPrice}>
360	                      {fmt(PLAN_PRICES[p][state.billing])}/mo
361	                    </span>
362	                  </button>
363	                ))}
364	              </div>
365	            </div>
366	
367	            {/* Team size slider */}
368	            <div className={styles.field}>
369	              <div className={styles.fieldHeader}>
370	                <label htmlFor={teamSizeId} className={styles.fieldLabel}>
371	                  Team Size
372	                  <Tooltip text={FIELD_TOOLTIPS.teamSize} />
373	                </label>
374	                <span className={styles.badge}>{state.teamSize} people</span>
375	              </div>
376	              <input
377	                id={teamSizeId}
378	                ref={teamSizeRef}
379	                type="range"
380	                min={1}
381	                max={200}
382	                step={1}
383	                value={state.teamSize}
384	                onChange={(e) => patch({ teamSize: Number(e.target.value) })}
385	                className={styles.slider}
386	              />
387	              <div className={styles.sliderRange}>
388	                <span>1</span>
389	                <span>200</span>
390	              </div>
391	            </div>
392	
393	            {/* Hours per week slider */}
394	            <div className={styles.field}>
395	              <div className={styles.fieldHeader}>
396	                <label htmlFor={manualHoursId} className={styles.fieldLabel}>
397	                  Hours / week on manual tasks
398	                  <Tooltip text={FIELD_TOOLTIPS.manualHours} />
399	                </label>
400	                <span className={styles.badge}>{state.manualHours} hrs</span>
401	              </div>
402	              <input
403	                id={manualHoursId}
404	                ref={manualHoursRef}
405	                type="range"
406	                min={1}
407	                max={40}
408	                step={0.5}
409	                value={state.manualHours}
410	                onChange={(e) =>
411	                  patch({ manualHours: Number(e.target.value) })
412	                }
413	                className={styles.slider}
414	              />
415	              <div className={styles.sliderRange}>
416	                <span>1 hr</span>
417	                <span>40 hrs</span>
418	              </div>
419	            </div>
420	
421	            {/* Hourly rate dollar input */}
422	            <DollarField
423	              label="Average Hourly Rate"
424	              tooltip={FIELD_TOOLTIPS.hourlyRate}
425	              value={state.hourlyRate}
426	              min={10}
427	              onChange={(v) => patch({ hourlyRate: v })}
428	            />
429	
430	            {/* Tool cost dollar input */}
431	            <DollarField
432	              label="Annual Tool & Contractor Cost"
433	              tooltip={FIELD_TOOLTIPS.toolCost}
434	              value={state.toolCost}
435	              min={0}
436	              onChange={(v) => patch({ toolCost: v })}
437	            />
438	          </div>
439	
440	          {/* RIGHT: Results */}
441	          <div className={styles.rightPanel}>
442	            {/* Hero savings card */}
443	            <div className={styles.heroCard}>
444	              <div className={styles.heroLabel}>
445	                Your Estimated Annual Savings
446	              </div>
447	              <div
448	                className={`${styles.heroAmount} ${netIsPositive ? styles.heroAmountPositive : styles.heroAmountNegative}`}
449	              >
450	                {fmt(result.savings)}
451	              </div>
452	              <div className={styles.heroMeta}>
453	                <span
454	                  className={`${styles.roiPill} ${netIsPositive ? styles.roiPillPositive : styles.roiPillNegative}`}
455	                >
456	                  {fmtRoi(result.roi)} ROI
457	                </span>
458	                <span className={styles.heroSubLabel}>in the first year</span>
459	              </div>
460	            </div>
461	
462	            {/* Metrics grid */}
463	            <div className={styles.metricsGrid}>
464	              <MetricCard
465	                label="Hours Saved"
466	                value={fmtHrs(result.hrsSaved)}
467	                sub="annually"
468	              />
469	              <MetricCard
470	                label="Monthly Benefit"
471	                value={fmt(result.monthlyBenefit)}
472	                sub="after plan cost"
473	              />
474	              <MetricCard
475	                label="Productivity Boost"
476	                value={fmtPct(result.prodGain)}
477	                sub="of total work hrs"
478	              />
479	              <MetricCard
480	                label="Total Gain"
481	                value={fmt(result.net)}
482	                sub="net over plan cost"
483	              />
484	            </div>
485	
486	            {/* Plan summary */}
487	            <div className={styles.planSummary}>
488	              <div className={styles.summaryRow}>
489	                <span className={styles.summaryLabel}>What You&apos;ll Pay</span>
490	                <span className={styles.summaryValue}>
491	                  {fmt(result.byr)}/yr
492	                </span>
493	              </div>
494	              <div className={styles.summaryDivider} />
495	              <div className={styles.summaryRow}>
496	                <span className={styles.summaryLabel}>Money You Keep</span>
497	                <span
498	                  className={`${styles.summaryValue} ${netIsPositive ? styles.summaryPositive : styles.summaryNegative}`}
499	                >
500	                  {fmt(result.net)}
501	                </span>
502	              </div>
503	            </div>
504	
505	            {/* CTA card */}
506	            <div className={styles.ctaCard}>
507	              <div className={styles.ctaHeadline}>
508	                You could save{" "}
509	                <span className={styles.ctaHighlight}>
510	                  {fmt(result.savings)}
511	                </span>{" "}
512	                this year
513	              </div>
514	              <p className={styles.ctaSubtitle}>
515	                Stop paying {fmt(result.laborSaved)} in labor on tasks Boldteq
516	                handles end-to-end.
517	              </p>
518	              <a
519	                href="/book-a-demo"
520	                className={styles.ctaButton}
521	              >
522	                Schedule a Free Demo
523	              </a>
524	              <div className={styles.trustBadges}>
525	                <span className={styles.trustBadge}>14-day guarantee</span>
526	                <span className={styles.trustBadgeDot} aria-hidden="true" />
527	                <span className={styles.trustBadge}>No lock-in</span>
528	                <span className={styles.trustBadgeDot} aria-hidden="true" />
529	                <span className={styles.trustBadge}>Cancel anytime</span>
530	              </div>
531	            </div>
532	          </div>
533	        </div>
534	      </div>
535	    </section>
536	  );
537	}
