1	/* ─── Section wrapper ─────────────────────────────────────────────────────── */
2	
3	.section {
4	  background-color: var(--color-brand-light-bg);
5	  padding: 80px 5%;
6	}
7	
8	.container {
9	  width: 100%;
10	  max-width: 1200px;
11	  margin: 0 auto;
12	}
13	
14	/* ─── Header ─────────────────────────────────────────────────────────────── */
15	
16	.header {
17	  text-align: center;
18	  display: flex;
19	  flex-direction: column;
20	  align-items: center;
21	  gap: 14px;
22	  margin-bottom: 32px;
23	}
24	
25	.eyebrowBadge {
26	  display: inline-flex;
27	  align-items: center;
28	  height: 32px;
29	  padding: 0 14px;
30	  background-color: rgba(33, 207, 255, 0.08);
31	  border: 1px solid var(--color-brand-cyan);
32	  border-radius: 20px;
33	  font-family: var(--font-roobert), Arial, sans-serif;
34	  font-size: 12px;
35	  font-weight: 700;
36	  color: var(--color-brand-card-border);
37	  letter-spacing: 0.04em;
38	  text-transform: capitalize;
39	}
40	
41	.title {
42	  color: var(--color-text-primary);
43	  font-family: var(--font-roobert), Arial, sans-serif;
44	  font-size: 36px;
45	  font-weight: 700;
46	  line-height: 1.2;
47	  margin: 0;
48	  max-width: 580px;
49	}
50	
51	.subtitle {
52	  color: rgba(8, 39, 83, 0.55);
53	  font-family: var(--font-roobert), Arial, sans-serif;
54	  font-size: 16px;
55	  line-height: 26px;
56	  max-width: 520px;
57	  margin: 0;
58	}
59	
60	/* ─── Preset buttons ─────────────────────────────────────────────────────── */
61	
62	.presets {
63	  display: flex;
64	  justify-content: center;
65	  gap: 10px;
66	  flex-wrap: wrap;
67	  margin-bottom: 32px;
68	}
69	
70	.presetBtn {
71	  display: inline-flex;
72	  align-items: center;
73	  gap: 6px;
74	  background-color: #fff;
75	  border: 1px solid #e2e8f0;
76	  border-radius: var(--radius-pill);
77	  padding: 8px 18px;
78	  font-family: var(--font-roobert), Arial, sans-serif;
79	  font-size: 14px;
80	  font-weight: 500;
81	  color: var(--color-text-primary);
82	  cursor: pointer;
83	  transition: border-color 0.15s ease, background-color 0.15s ease, color 0.15s ease;
84	}
85	
86	.presetBtn:hover {
87	  border-color: var(--color-brand-card-border);
88	  color: var(--color-brand-card-border);
89	}
90	
91	.presetBtnActive {
92	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
93	  border-color: transparent;
94	  color: #fff;
95	}
96	
97	.presetBtnActive:hover {
98	  color: #fff;
99	  filter: brightness(1.06);
100	}
101	
102	/* ─── Two-column layout ──────────────────────────────────────────────────── */
103	
104	.layout {
105	  display: grid;
106	  grid-template-columns: 1fr 1fr;
107	  gap: 24px;
108	  align-items: start;
109	}
110	
111	/* ─── Left panel ─────────────────────────────────────────────────────────── */
112	
113	.leftPanel {
114	  background-color: #fff;
115	  border: 1px solid #e8eaed;
116	  border-radius: 20px;
117	  padding: 32px;
118	  display: flex;
119	  flex-direction: column;
120	  gap: 24px;
121	  box-shadow: 0 4px 24px rgba(8, 39, 83, 0.06);
122	}
123	
124	.panelTitle {
125	  color: var(--color-text-primary);
126	  font-family: var(--font-roobert), Arial, sans-serif;
127	  font-size: 13px;
128	  font-weight: 700;
129	  text-transform: uppercase;
130	  letter-spacing: 0.07em;
131	}
132	
133	/* ─── Plan selection block ───────────────────────────────────────────────── */
134	
135	.planBlock {
136	  display: flex;
137	  flex-direction: column;
138	  gap: 12px;
139	}
140	
141	/* Billing toggle */
142	.billingToggle {
143	  display: flex;
144	  background-color: var(--color-brand-light-bg);
145	  border-radius: 10px;
146	  padding: 5px 6px;
147	  gap: 4px;
148	}
149	
150	.billingBtn {
151	  flex: 1;
152	  display: flex;
